@prefix hb: <https://data.hanbit.example/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
hb:p1 a hb:Patient ;
  hb:birthDate "1980-03-02"^^xsd:date ;
  hb:hasLabResult hb:r1 .
hb:r1 hb:value 5.6 ; hb:unit "mmol/L" .

hb:DiabeticPatient owl:equivalentClass [
  owl:intersectionOf ( hb:Patient
    [ a owl:Restriction ;
      owl:onProperty hb:hasDiagnosis ;
      owl:someValuesFrom hb:Diabetes ] ) ] .

PREFIX hb: <https://data.hanbit.example/>
SELECT ?p ?name WHERE {
  ?p a hb:Patient ; hb:name ?name ;
     hb:hasDiagnosis ?d ; hb:takes hb:Metformin .
  ?d a hb:Diabetes .
}

hb:PatientShape a sh:NodeShape ;
  sh:targetClass hb:Patient ;
  sh:property [ sh:path hb:birthDate ;
    sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:date ;
    sh:severity sh:Violation ] .
